import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-03-23","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-03-23","date":"2021-03-23T00:00:00.000Z","updated":"2021-03-24T00:00:00.000Z","tags":["Ceph","Orchestrator","Distributed Storage","Meeting Summary","Technical Discussion"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-03-23.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-03-23.md","lastUpdated":1780459816000}'),a={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-03-23.md"};function s(l,e,p,n,_,c){return r(),o("div",null,[...e[0]||(e[0]=[i("<p>本次Ceph Orchestrator会议主要讨论了以下几个议题：</p><ol><li><p><strong>OC服务拉取请求</strong>：决定将所有非托管的OSD整合到一个OS服务中，并在删除服务时提示用户先删除相关OSD。讨论了OSD.unmanaged的命名问题，认为这是一个合适的名称。</p></li><li><p><strong>卷设置容器版本问题</strong>：讨论了卷设置时使用与管理器相同容器版本的问题，确认该拉取请求尚未合并，但认为当前的实现方式是可行的。</p></li><li><p><strong>HA RGW服务设计问题</strong>：讨论了HA RGW服务的设计，建议将HAProxy和Keepalived分开成两个独立的服务，以便更灵活地使用它们。讨论了服务的配置和密码管理问题，建议自动生成密码并存储在配置文件中。</p></li><li><p><strong>OSD内存自动配置</strong>：提到了OSD内存自动配置的问题，但目前该议题被暂时搁置。</p></li><li><p><strong>Rook Orchestrator的状态</strong>：讨论了Rook Orchestrator的状态，确认其基本功能可用，但需要进一步的测试和功能完善。</p></li></ol><p>会议决定事项：</p><ul><li>将所有非托管的OSD整合到一个OS服务中，并在删除服务时提示用户先删除相关OSD。</li><li>考虑将HA RGW服务中的HAProxy和Keepalived分开成两个独立的服务。</li><li>自动生成密码并存储在配置文件中，以简化用户配置。</li></ul><p>后续行动计划：</p><ul><li>继续跟进OC服务的拉取请求，确保其顺利合并。</li><li>对HA RGW服务进行重构，将其分为HAProxy和Keepalived两个独立的服务。</li><li>测试和完善Rook Orchestrator的功能，确保其稳定性和可用性。</li><li>关注OSD内存自动配置的问题，适时重启相关工作。</li></ul><p>会议还确认了Pacific版本的预期发布日期，并讨论了与OpenStack Wallaby版本的集成问题。感谢OpenStack团队的支持，并讨论了未来可能的合作方向。</p>",7)])])}const g=t(a,[["render",s]]);export{d as __pageData,g as default};
